#include <BLEDevice.h>
#include <BLEBeacon.h>
#include <BLEAdvertising.h>

void setup() {
  BLEDevice::init("Room-Beacon");
  BLEBeacon beacon;
  beacon.setManufacturerId(0x4C00);
  beacon.setProximityUUID(BLEUUID("74278BDA-B644-4520-8F0C-720EAF059935"));
  beacon.setMajor(1);
  beacon.setMinor(1);
  beacon.setSignalPower(-59);

  BLEAdvertisementData data;
  data.setFlags(0x04);
  data.setManufacturerData(beacon.getData());
  BLEAdvertising* advertising = BLEDevice::getAdvertising();
  advertising->setAdvertisementData(data);
  advertising->start();
}

void loop() {
  delay(1000);
}

import 'package:flutter_blue_plus/flutter_blue_plus.dart';

Future<void> scanBeacons() async {
  final subscription = FlutterBluePlus.onScanResults.listen((results) {
    for (final result in results) {
      final manufacturerData =
          result.advertisementData.manufacturerData[0x004C];
      if (manufacturerData != null) {
        print('Beacon candidate RSSI: ${result.rssi} dBm');
      }
    }
  });
  await FlutterBluePlus.startScan(timeout: const Duration(seconds: 5));
  await FlutterBluePlus.stopScan();
  await subscription.cancel();
}

import 'dart:async';
import 'package:flutter_blue_plus/flutter_blue_plus.dart';

Future<StreamSubscription<List<int>>> listenToSensor(
  BluetoothDevice device,
  Guid serviceId,
  Guid characteristicId,
) async {
  await device.connect();
  final services = await device.discoverServices();
  final service = services.firstWhere((item) => item.uuid == serviceId);
  final characteristic =
      service.characteristics.firstWhere((item) => item.uuid == characteristicId);
  await characteristic.setNotifyValue(true);
  return characteristic.onValueReceived.listen((bytes) {
    if (bytes.isNotEmpty) {
      print('Sensor byte: ${bytes.first}');
    }
  });
}
